    },
    {
      "kind": "make-support-conditional",
      "description": "A supporting decider who received an open concern makes its support wait on that concern."
    },
    {
      "kind": "restore-full-support",
      "description": "A decider whose condition's concern is resolved gives full support again."
    },
    {
      "kind": "resolve-concern",
      "description": "Whoever holds a concern's information starts the remedy; 2 rounds later the concern is resolved."
    },
    {
      "kind": "resolve-own-concern",
      "description": "The person a concern reached starts the remedy on their own side; 2 rounds later it is resolved."
    },
    {
      "kind": "object-to-remedy",
      "description": "Whoever holds a concern's information finds the remedy under way misses the point; the remedy stops part-way and the concern is open again."
    },
    {
      "kind": "raise-new-concern",
      "description": "Whoever holds a resolved concern's information raises a new local concern on the same matter, through the same channel to the same person."
    },
    {
      "kind": "reopen-concern",
      "description": "The person a resolved concern reached finds the answer wanting and reopens it, once; the answer the next remedy gives stands."
    },
    {
      "kind": "put-matter-on-agenda",
      "description": "Anyone puts a matter before the group while the decision is open or in effect; it stays on the agenda until someone settles it."
    },
    {
      "kind": "settle-agenda-matter",
      "description": "Anyone settles one of the matters still open on the group's agenda."
