   "compiled": true
  },
  {
   "kind": "restore-full-support",
   "description": "A decider whose condition's concern is resolved gives full support again.",
   "compiled": true
  },
  {
   "kind": "resolve-concern",
   "description": "Whoever holds a concern's information starts the remedy; 2 rounds later the concern is resolved.",
   "compiled": true
  },
  {
   "kind": "resolve-own-concern",
   "description": "The person a concern reached starts the remedy on their own side; 2 rounds later it is resolved.",
   "compiled": true
  },
  {
   "kind": "object-to-remedy",
   "description": "Whoever holds a concern's information finds the remedy under way misses the point; the remedy stops part-way and the concern is open again.",
   "compiled": true
  },
  {
   "kind": "raise-new-concern",
   "description": "Whoever holds a resolved concern's information raises a new local concern on the same matter, through the same channel to the same person.",
   "compiled": true
  },
  {
   "kind": "reopen-concern",
   "description": "The person a resolved concern reached finds the answer wanting and reopens it, once; the answer the next remedy gives stands.",
   "compiled": true
  },
  {
   "kind": "put-matter-on-agenda",
   "description": "Anyone puts a matter before the group while the decision is open or in effect; it stays on the agenda until someone settles it.",
   "compiled": true
  },
  {
   "kind": "settle-agenda-matter",
   "description": "Anyone settles one of the matters still open on the group's agenda.",
   "compiled": true
  },
  {
   "kind": "bring-decision-back",
   "description": "A decider puts a rejected decision back on the table; it is decided again 6 rounds later.",
   "compiled": true
  },
  {
   "kind": "discuss-local-concern-at-meeting",
   "description": "At a scheduled partnership meeting, discuss a local concern and its implications; the discussion can lengthen the meeting.",
   "compiled": false
  },
  {
   "kind": "raise-local-surveillance-concern",
   "description": "Raise a new local surveillance concern for partnership consideration, identifying the affected matter and the person it should reach.",
   "compiled": false
  },
  {
   "kind": "assess-early-warning-system",
   "description": "Assess the early-warning system's technical readiness and provide findings or recommendations that can inform deployment deliberations.",
   "compiled": false
  },
  {
   "kind": "draft-cross-border-arrangement",
   "description": "Prepare or revise a legal arrangement for cross-border operation of the system and provide it for partnership consideration.",
   "compiled": false
  },
  {
   "kind": "prepare-implementation-plan",
   "description": "Develop or revise a practical logistics plan for deploying the system and provide it for partnership consideration.",
   "compiled": false
  }
 ]
}"}]

