[{"role": "system", "content": "Propose the actions people can attempt so the listed behaviors can happen. An action is something a person chooses to try (hold a meeting, reopen an issue, attach a condition to support, vote, deploy); things that happen on their own each tick are processes and are not actions. Do not repeat an existing action or propose another that does what one already does. Fields name the entities or values the attempt needs (entity_ref for an entity); the person attempting it is implied, so never add an actor field. Name in for_behaviors the request_ids each action serves. This world keeps running for many rounds, so also propose the actions that move things back and forward: for every action that raises, blocks, delays, withholds or reopens something, an action someone can take to address, resolve, restore or reconsider it (for example addressing a raised concern, making a readiness complete, giving full support again, reconsidering a postponed decision). Every person listed must have at least one action that fits their position and that they could take more than once over the run; specialist groups need actions that do their specialist work. List such an action under the behavior whose state it moves back. When several people share a position (for example member countries), what the description says one of them does is an example of what the position allows, not a limit: write the action so any of them can take it. When existing_actions already cover something (a group decision's giving, conditioning and restoring support, resolving and reopening concerns, and its deadline settling it), do not propose another action for it; propose the practical and specialist work instead."}, {"role": "user", "content": "{
  "people": [
    {
      "id": "country_one",
      "position": "Member country of the partnership"
    },
    {
      "id": "country_two",
      "position": "Member country of the partnership"
    },
    {
      "id": "country_three",
      "position": "Member country of the partnership"
    },
    {
      "id": "country_four",
      "position": "Member country of the partnership"
    },
    {
      "id": "regional_health_network",
      "position": "Regional health network participating in the partnership"
    },
    {
      "id": "partnership",
      "position": "Partnership of four countries and a regional health network"
    },
    {
      "id": "technical_group",
      "position": "Technical group advising on the early-warning system"
    },
    {
      "id": "legal_group",
      "position": "Legal group advising on cross-border arrangements"
    },
    {
      "id": "logistics_group",
      "position": "Logistics group advising on implementation"
    },
    {
      "id": "community_group",
      "position": "Community group raising local concerns about surveillance"
    }
  ],
  "behaviors_to_cover": [
    {
      "request_id": "regular_member_meetings",
      "behavior": "Partnership members meet regularly to consider activation and discuss concerns.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "concerns_slow_meetings",
      "behavior": "Local concerns can lengthen or slow partnership meetings as members discuss their implications.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "settled_issues_reopen",
      "behavior": "A concern can cause members to reopen an issue they had previously treated as settled.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "concerns_delay_deployment",
      "behavior": "Concern-driven deliberation or conditional support can delay deployment beyond the planned decision process.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "concerns_block_deployment",
      "behavior": "If members do not provide sufficient support by the deadline, the system may not be activated and deployment can be blocked.",
      "classification": "to_generate",
      "by": null
    }
  ],
  "existing_actions": [
    {
      "kind": "communicate",
      "description": "Deliver one represented information item to its declared recipient."
    },
    {
      "kind": "give-support",
      "description": "A decider who does not yet support the decision gives it full support."
    },
    {
      "kind": "make-support-conditional",
      "description": "A supporting decider who received an open concern makes its support wait on that concern."
    },
    {
      "kind": "restore-full-support",
      "description": "A decider whose condition's concern is resolved gives full support again."
    },
    {
      "kind": "resolve-concern",
      "description": "Whoever holds a concern's information starts the remedy; 2 rounds later the concern is resolved."
    },
    {
      "kind": "resolve-own-concern",
      "description": "The person a concern reached starts the remedy on their own side; 2 rounds later it is resolved."
    },
